const fs = require('fs');
const path = require('path');
const { chromium } = require('playwright');

const files = ['tokens.css','base.css','components.css','pages.css'];
const source = {};
for (const f of files) source[f] = fs.readFileSync(path.join('site/css', f), 'utf8');

function decls(css) {
  // strip comments
  css = css.replace(/\/\*[\s\S]*?\*\//g, '');
  const out = [];
  const ruleRe = /([^{}]+)\{([^{}]*)\}/g; let m;
  while ((m = ruleRe.exec(css))) {
    const sel = m[1].trim().replace(/\s+/g,' ');
    const body = m[2];
    const props = [];
    const dRe = /([a-zA-Z-]+)\s*:\s*([^;]+)/g; let d;
    while ((d = dRe.exec(body))) props.push([d[1].trim(), d[2].trim()]);
    out.push({sel, props});
  }
  return out;
}

(async () => {
  const b = await chromium.launch();
  const p = await b.newPage();
  await p.goto('file://' + process.cwd() + '/site/index.html');
  const cssom = await p.evaluate(() => {
    const res = [];
    for (const ss of document.styleSheets) {
      let rules; try { rules = ss.cssRules; } catch(e) { res.push({error: String(e), href: ss.href}); continue; }
      const walk = (list) => {
        for (const r of list) {
          if (r.cssRules) walk(r.cssRules);
          else if (r.selectorText) res.push({sel: r.selectorText.replace(/\s+/g,' '), props: [...r.style].map(prop => [prop, r.style.getPropertyValue(prop)])});
          else if (r.cssText) res.push({raw: r.cssText});
        }
      };
      walk(rules);
    }
    return res;
  });
  console.log('CSSOM rules:', cssom.length, 'errors:', cssom.filter(r=>r.error).length);

  const norm = s => s.replace(/\s*,\s*/g, ',').replace(/>/g,'>').replace(/\s+/g,' ').trim();
  const index = new Map();
  for (const r of cssom) {
    if (!r.sel) continue;
    const key = norm(r.sel);
    if (!index.has(key)) index.set(key, new Set());
    for (const [prop] of r.props) index.get(key).add(prop);
  }
  let problems = 0;
  for (const f of files) {
    for (const rule of decls(source[f])) {
      // split selector list
      for (const sel of rule.sel.split(',').map(norm)) {
        if (!index.has(sel)) { console.log(`NO RULE [${f}] ${sel}`); problems++; continue; }
        for (const [prop, val] of rule.props) {
          if (!index.get(sel).has(prop)) { console.log(`DROPPED [${f}] ${sel} { ${prop}: ${val} }`); problems++; }
        }
      }
    }
  }
  console.log('problems:', problems);
  await b.close();
})();
