node - <<'EOF'
const { chromium } = require('playwright');
const pages = ['index','products','pricing','orders','about','contact'];
(async () => {
  const b = await chromium.launch();
  for (const vw of [1280, 390]) {
    console.log('=== viewport', vw);
    for (const name of pages) {
      const p = await b.newPage({ viewport: { width: vw, height: 900 } });
      const fails = [];
      p.on('requestfailed', r => fails.push('REQFAIL ' + r.url()));
      p.on('console', m => { if (m.type() === 'error') fails.push('CONSOLE ' + m.text()); });
      await p.goto('file://' + process.cwd() + '/site/' + name + '.html');
      await p.waitForLoadState('load');
      const info = await p.evaluate(() => {
        const out = [];
        const de = document.documentElement;
        if (de.scrollWidth > de.clientWidth + 1) out.push(`h-overflow doc ${de.scrollWidth}>${de.clientWidth}`);
        for (const el of document.querySelectorAll('*')) {
          const r = el.getBoundingClientRect();
          const cs = getComputedStyle(el);
          if (cs.display === 'none' || cs.visibility === 'hidden') continue;
          if (r.width < 1 || r.height < 1) out.push(`zero ${el.tagName}.${el.className} ${r.width}x${r.height}`);
          if (r.right > window.innerWidth + 1 && cs.position !== 'fixed') out.push(`offscreen ${el.tagName}.${el.className} right=${r.right.toFixed(0)}`);
          if (el.tagName === 'IMG' && (!el.complete || el.naturalWidth === 0)) out.push(`img broken ${el.src}`);
          if (el.children.length === 0 && (el.textContent||'').trim() && cs.color === cs.backgroundColor) out.push(`invisible text ${el.tagName}.${el.className}`);
        }
        // overlaps among block siblings? skip
        return out;
      });
      console.log(name, info.length ? info.slice(0,8) : 'ok', fails.length ? fails : '');
      await p.close();
    }
  }
  await b.close();
})();
EOF

