import glob, re, os
for f in sorted(glob.glob('site/*.html')):
    s=open(f).read()
    for href in re.findall(r'href="([^"]+)"', s):
        if href.startswith(('http','#','mailto')): continue
        target=os.path.normpath(os.path.join(os.path.dirname(f), href))
        if not os.path.exists(target): print('MISSING', f, href)
    print(f, 'aria-current count:', s.count('aria-current="page"'), 'h1 count:', s.count('<h1'))
EOF

