input.command:
cat > "$TMPDIR/check.js" <<'EOF'
const { chromium } = require('playwright');
const http = require('http');
(async () => {
  const server = require('./server.js');
  const port = 4321;
  // server.js listens on PORT; start via child
  const { spawn } = require('child_process');
  const proc = spawn(process.execPath, ['server.js'], { env: { ...process.env, PORT: String(port) }, stdio: 'ignore' });
  await new Promise(r => setTimeout(r, 800));
  const browser = await chromium.launch();
  const pages = ['index','products','pricing','orders','about','contact'];
  for (const w of [390, 720, 721, 1280]) {
    const page = await browser.newPage({ viewport: { width: w, height: 900 } });
    for (const name of pages) {
      await page.goto(`http://127.0.0.1:${port}/${name}.html`);
      const m = await page.evaluate(() => ({
        sw: document.documentElement.scrollWidth,
        iw: window.innerWidth,
        sh: document.documentElement.scrollHeight,
        bodyBg: getComputedStyle(document.body).backgroundColor,
        font: getComputedStyle(document.body).fontFamily,
        fontLoaded: document.fonts.check('16px "Acme Sans"'),
      }));
      console.log(w, name, JSON.stringify(m));
    }
    await page.close();
  }
  await browser.close();
  proc.kill();
})();
EOF
node "$TMPDIR/check.js"

